package com.toir.service.repair;

import com.toir.dto.repaircampaign.*;
import com.toir.entity.Counteragent;
import com.toir.entity.repair.*;
import com.toir.entity.users.*;
import com.toir.enums.*;
import com.toir.exception.RestException;
import com.toir.repository.CounteragentRepository;
import com.toir.repository.projects.BrigadeRepository;
import com.toir.repository.repair.*;
import com.toir.repository.users.EmployeeRepository;
import com.toir.security.ScopeAccessService;
import com.toir.util.AuditBuilderService;
import lombok.RequiredArgsConstructor;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.*;

@Service @RequiredArgsConstructor
public class RepairCampaignResourcePolicy {
    private final RepairCampaignRepository campaigns; private final RepairCampaignWorkItemRepository items;
    private final RepairCampaignResourceAssignmentRepository assignments; private final EmployeeRepository employees;
    private final BrigadeRepository brigades; private final CounteragentRepository counteragents;
    private final ScopeAccessService scope; private final AuditBuilderService audit;

    @Transactional(readOnly=true) public List<RepairCampaignResourceResponse> list(UUID campaignId){var c=find(campaignId,false);return rows(campaignId).stream().map(a->response(a,c.getVersion(),true)).toList();}
    @Transactional public RepairCampaignResourceResponse add(UUID campaignId,RepairCampaignResourceRequest r){var c=find(campaignId,true);version(c,r.version());mutable(c);items.findByIdAndCampaignIdAndIsDeletedFalse(r.workItemId(),campaignId).orElseThrow(()->RestException.badRequest("RESOURCE_FOREIGN_ITEM"));validateRequest(r);validateResource(r);var active=rows(campaignId);if(active.stream().anyMatch(a->sameResource(a,r)&&overlap(a.getPlannedStartAt(),a.getPlannedEndAt(),r.plannedStartAt(),r.plannedEndAt())))throw RestException.conflict("RESOURCE_CONFLICT");var a=new RepairCampaignResourceAssignment();a.setRepairCampaignId(campaignId);a.setWorkItemId(r.workItemId());a.setEmployeeId(r.employeeId());a.setBrigadeId(r.brigadeId());a.setCounteragentId(r.counteragentId());a.setShiftCode(r.shiftCode().trim());a.setPlannedStartAt(r.plannedStartAt());a.setPlannedEndAt(r.plannedEndAt());a.setCompetencyRequirement(norm(r.competencyRequirement()));try{assignments.saveAndFlush(a);}catch(DataIntegrityViolationException e){if(messages(e).contains("uq_repair_campaign_resources_active_identity"))throw RestException.conflict("RESOURCE_CONFLICT");throw e;}var out=response(a,touch(c),true);audit.log("repair_campaign_resource",a.getId().toString(),AuditAction.CREATE,AuditModule.REPAIR_CAMPAIGN,"Resource assigned",null,out);return out;}
    @Transactional public RepairCampaignResourceResponse remove(UUID campaignId,UUID id,Long v){var c=find(campaignId,true);version(c,v);mutable(c);var a=assignments.findByIdAndRepairCampaignIdAndIsDeletedFalse(id,campaignId).orElseThrow(()->RestException.notFound("Resource assignment not found"));var before=response(a,c.getVersion(),true);a.setDeleted(true);assignments.saveAndFlush(a);var out=response(a,touch(c),false);audit.log("repair_campaign_resource",id.toString(),AuditAction.DELETE,AuditModule.REPAIR_CAMPAIGN,"Resource removed",before,out);return out;}
    public List<String> blockers(UUID campaignId){var resources=rows(campaignId);List<String>b=new ArrayList<>();var work=items.findAllByCampaignIdAndIsDeletedFalseOrderByOrderNumberAsc(campaignId);Set<UUID>assigned=new HashSet<>();resources.forEach(a->assigned.add(a.getWorkItemId()));work.stream().filter(i->i.getPriority()==RepairCampaignPriority.CRITICAL&&!assigned.contains(i.getId())).forEach(i->b.add("CRITICAL_WORK_UNASSIGNED:"+i.getId()));for(int i=0;i<resources.size();i++)for(int j=i+1;j<resources.size();j++){var a=resources.get(i);var x=resources.get(j);if(sameResource(a,x)&&overlap(a.getPlannedStartAt(),a.getPlannedEndAt(),x.getPlannedStartAt(),x.getPlannedEndAt()))b.add("RESOURCE_CONFLICT:"+a.getId()+":"+x.getId());}return b.stream().sorted().toList();}
    public boolean assigned(UUID campaignId,UUID itemId){return assignments.existsByRepairCampaignIdAndWorkItemIdAndIsDeletedFalse(campaignId,itemId);}
    private void validateRequest(RepairCampaignResourceRequest r){if(r==null||r.shiftCode()==null||r.shiftCode().isBlank()||r.plannedStartAt()==null||r.plannedEndAt()==null||!r.plannedEndAt().isAfter(r.plannedStartAt()))throw RestException.badRequest("RESOURCE_WINDOW_INVALID");if((r.employeeId()!=null?1:0)+(r.brigadeId()!=null?1:0)+(r.counteragentId()!=null?1:0)!=1)throw RestException.badRequest("RESOURCE_EXACTLY_ONE_REQUIRED");}
    private void validateResource(RepairCampaignResourceRequest r){String need=norm(r.competencyRequirement());if(r.employeeId()!=null){Employee e=employees.findByIdAndIsDeletedFalse(r.employeeId()).filter(Employee::isActive).orElseThrow(()->RestException.badRequest("RESOURCE_INACTIVE"));if(need!=null&&!matches(need,e.getPosition(),e.getGrade(),e.getSpecialisationId()==null?null:e.getSpecialisationId().toString()))throw RestException.badRequest("COMPETENCY_MISSING");}else if(r.brigadeId()!=null){Brigade b=brigades.findByIdAndIsDeletedFalse(r.brigadeId()).filter(Brigade::isActive).orElseThrow(()->RestException.badRequest("RESOURCE_INACTIVE"));if(need!=null&&!matches(need,b.getSpecialization()))throw RestException.badRequest("COMPETENCY_MISSING");}else{Counteragent c=counteragents.findByIdAndIsDeletedFalse(r.counteragentId()).filter(x->x.getStatus()==CounteragentStatus.ACTIVE).orElseThrow(()->RestException.badRequest("RESOURCE_INACTIVE"));if(need!=null)throw RestException.badRequest("COMPETENCY_MISSING");}}
    private RepairCampaign find(UUID id,boolean lock){var c=(lock?campaigns.findLockedByIdAndIsDeletedFalse(id):campaigns.findByIdAndIsDeletedFalse(id)).orElseThrow(()->RestException.notFound("Campaign not found"));scope.assertCanAccessDepartment(c.getDepartmentId());return c;}private static void version(RepairCampaign c,Long v){if(v==null||!Objects.equals(v,c.getVersion()))throw RestException.conflict("CAMPAIGN_VERSION_CONFLICT");}private static void mutable(RepairCampaign c){if(c.getStatus()==RepairCampaignStatus.PENDING_APPROVAL)throw RestException.conflict("CAMPAIGN_PLANNING_APPROVAL_INVALIDATION_REQUIRED");if(c.getStatus().ordinal()>=RepairCampaignStatus.APPROVED.ordinal())throw RestException.conflict("CAMPAIGN_PLANNING_FROZEN");}private long touch(RepairCampaign c){c.setUpdatedAt(Instant.now());return campaigns.saveAndFlush(c).getVersion();}private List<RepairCampaignResourceAssignment> rows(UUID id){return assignments.findAllByRepairCampaignIdAndIsDeletedFalseOrderByPlannedStartAtAscIdAsc(id);}private static boolean overlap(Instant a,Instant b,Instant c,Instant d){return a.isBefore(d)&&c.isBefore(b);}private static boolean sameResource(RepairCampaignResourceAssignment a,RepairCampaignResourceRequest r){return Objects.equals(a.getEmployeeId(),r.employeeId())&&Objects.equals(a.getBrigadeId(),r.brigadeId())&&Objects.equals(a.getCounteragentId(),r.counteragentId());}private static boolean sameResource(RepairCampaignResourceAssignment a,RepairCampaignResourceAssignment r){return Objects.equals(a.getEmployeeId(),r.getEmployeeId())&&Objects.equals(a.getBrigadeId(),r.getBrigadeId())&&Objects.equals(a.getCounteragentId(),r.getCounteragentId());}private static boolean matches(String n,String...v){return Arrays.stream(v).filter(Objects::nonNull).map(String::trim).anyMatch(x->x.equalsIgnoreCase(n));}private static String norm(String s){return s==null||s.isBlank()?null:s.trim();}private static String messages(Throwable e){StringBuilder s=new StringBuilder();for(Throwable x=e;x!=null;x=x.getCause())s.append(' ').append(x.getMessage());return s.toString();}
    private static RepairCampaignResourceResponse response(RepairCampaignResourceAssignment a,long v,boolean active){return new RepairCampaignResourceResponse(a.getId(),a.getRepairCampaignId(),a.getWorkItemId(),a.getEmployeeId(),a.getBrigadeId(),a.getCounteragentId(),a.getShiftCode(),a.getPlannedStartAt(),a.getPlannedEndAt(),a.getCompetencyRequirement(),v,active);}
}
